  /* ==================== PC-56 TENANT-2c · bulk listing upload (W128 + W2355–W2356) ==================== */
  'limport.title': 'Bulk upload listings',
  'limport.subtitle': 'CSV or Excel — one row per lot. Every row is validated before anything is created; a bad row never blocks the good ones.',
  'limport.trustPath': 'Bulk-created listings walk the normal path: draft → member consent → QC → published. Bulk speeds entry, it never skips trust — nothing here reaches a buyer without a reviewer approving it.',
  'limport.consentNote': 'Each row lists someone else’s produce, so each member must have recorded their on-behalf consent (voice or app tap). Rows without it are flagged for a fix, never silently dropped — their produce, their yes.',
  'limport.kycGap': 'The canon’s “KYC pending — draft allowed, publish blocks until verified” is half-built on purpose: the draft IS allowed, but no KYC gate exists on publish anywhere on this platform (the per-role KYC map governs payouts and has no listing purpose). Inventing one here would apply a rule to imported lots and not to console-created ones — named as backend work instead of faked.',
  'limport.templateHeading': 'Template',
  'limport.templateNote': 'Columns: {columns}. Generated from the same list the importer parses, so the template cannot drift from the parser.',
