  'od.tdsNote': 'A note on TDS, because the section matters: this platform deducts under 194-O (the marketplace operator’s deduction on the seller’s gross) at SETTLEMENT — it appears on the settlement statement, not on the order row. Section 194Q is the buyer’s own deduction on purchases above the annual threshold and is the buyer’s filing, not ours. ₹0 here means no deduction applied at order time, never that one was waived.',

  // ---- PC-56 TENANT-3b · W140 the disputes desk, W141's money card, the refund maker-checker plane ----
