  // PC-56 TENANT-4c · W147/W148 — the settlement cycle and the statements it produces.
  'stl.title': 'Settlements',
  'stl.intro': 'Per-seller settlement cycles: gross sales − commission − tax = net paid. Closing a cycle turns a period of trade into statements your members can hold, and it takes two people.',
  'stl.restricted': 'Settlement cycles need the settlement.close permission. Ask an admin — a cycle is not affected either way.',
  'stl.loadError': 'The cycle could not be loaded. Nothing about the period has changed. Retry.',
  'stl.noCycle': 'No cycle has opened yet. A cycle opens as soon as your first sale settles inside its period.',
  'stl.currentCycle': 'Current cycle',
  'stl.cycleGrossHint': '{sellers} sellers with unsettled sales · {period}',
  'stl.status.open': 'open',
  'stl.status.pending_close': 'awaiting a second person',
  'stl.status.closing': 'closing — statements generating',
  'stl.status.closed': 'closed',
  'stl.status.rejected': 'close rejected',
  'stl.status.unknown': 'unknown state',
  'stl.progressTitle': 'Statements',
  'stl.progress.notStarted': 'No statements yet. They generate once a second person approves the close.',
  'stl.progress.generating': '{generated} of {expected} generated · {remaining} to go',
  'stl.progress.complete': 'All {generated} statements generated.',
  'stl.progress.overGenerated': '{generated} statements exist where {expected} were expected. A seller gained sales after the close was approved — worth checking which.',
  'stl.progressHint': 'Each statement is its own transaction, so a failure part-way through costs one seller a retry rather than the whole period. That is also why this shows a count instead of claiming everything happens at once: one transaction over a hundred thousand sellers is not something any database should be asked to hold.',
  'stl.signatures': 'Signatures',
  'stl.notRequested': 'No close has been requested for this cycle.',
  'stl.requestedAt': 'Close requested {at}',
  'stl.decidedAt': 'Decided {at}',
  'stl.twoHumans': 'A cycle close always needs two people: one requests it, a different one approves. There is no amount below which one person is enough — a cycle is a period of somebody’s livelihood, not a figure.',
  'stl.closeTitle': 'Close this cycle',
  'stl.requestConfirm': 'Request the close of this cycle: {sellers} sellers, {gross} of gross sales. A different admin then approves it, and statements generate after that.',
  'stl.requestClose': 'Request close',
  'stl.closeBlocked.noPermission': 'Closing a cycle needs the settlement.close permission.',
  'stl.closeBlocked.notOpen': 'This cycle is not open — it is already in the close process or finished.',
  'stl.closeBlocked.periodNotEnded': 'This cycle’s last day has not finished yet. Closing early would leave sales that happen today out of the period they belong to, and the seller would never learn which statement they landed in.',
  'stl.closeBlocked.nothingToSettle': 'There are no unsettled sales in this period, so there is nothing to close.',
  'stl.youRequested': 'You requested this close, so you may not also approve it. Ask another admin to sign it — you can still reject your own request.',
  'stl.approveConfirm': 'Approve the close for {sellers} sellers. Statements generate after this, one per seller.',
  'stl.approveClose': 'Approve close',
  'stl.noteOptional': 'Note (optional)',
  'stl.rejectNote': 'Why are you rejecting this close? The requester is told.',
  'stl.rejectNoteHint': 'At least {floor} characters. The cycle returns to open and can be requested again once the reason is dealt with.',
  'stl.rejectClose': 'Reject with reason',
  'stl.generate': 'Generate statements',
  'stl.generateHint': 'Generate the next batch of statements for this cycle. Press it again while a remainder is showing — the work resumes rather than restarting, so a large tenant finishes in passes instead of one enormous transaction.',
  'stl.sellersTitle': 'Sellers in this cycle',
  'stl.sellersEmpty': 'No unsettled sales in this period yet. Sellers appear here as orders complete.',
  'stl.colSeller': 'Seller',
  'stl.colOrders': 'Orders',
  'stl.colGross': 'Gross',
  'stl.colCommission': 'Commission',
  'stl.colTax': 'Tax',
  'stl.colNet': 'Net',
  'stl.netMismatch': 'does not add up',
  'stl.deduction.buyer': 'Commission and tax read ₹0 because your organisation charges BUYERS, not sellers — so a seller keeps their full gross. The columns exist because a seller-side organisation would see real deductions in them.',
  'stl.deduction.seller': 'Your organisation charges SELLERS, so the commission and tax deducted from each seller’s gross appear in these columns.',
