  'ak.list.title': 'API keys',
  'ak.list.lede': 'Programmatic access to your data. A key is shown once, at creation, and stored only as a sha256 hash — nobody, including the platform, can read it back. Scopes are exact allow-lists: a key does exactly what it says, nothing more, and never more than the administrator who created it. Only live keys exist — this platform has no sandbox mode.',
